<?php
declare(strict_types=1);
require __DIR__.'/recurring-bookings.php';
use Wellness\Auth\{AuthContext,ApplicationAdminContext,VerifiedIdentity};
use Wellness\Service\{LocationDiscoveryService,TravelEnquiryService};
use Wellness\Http\ApiException;
$pdo->exec(file_get_contents(dirname(__DIR__,2).'/database/migrations/038_practitioner_private_locations.sql'));
$pdo->exec(file_get_contents(dirname(__DIR__,2).'/database/migrations/048_location_discovery.sql'));
$pdo->exec(file_get_contents(dirname(__DIR__,2).'/database/migrations/048_location_discovery.sql'));
$pdo->exec("UPDATE services SET published=1 WHERE id=4; UPDATE practitioner_services SET offers_mobile=1,mobile_radius_km=50,mobile_free_radius_km=20 WHERE practitioner_id=3 AND service_id=4;
 UPDATE locations SET address_line1='1 Synthetic Street',city='Toronto',province='Ontario',postal_code='M5V 1A1' WHERE id=1;
 INSERT INTO public_team_profiles(user_id,clinic_id,slug,section,public_name,public_title,published,show_booking_action) VALUES(2,1,'synthetic','practitioner','Synthetic practitioner','RMT',1,1)");
$calls=[];$road=60000;
$transport=function(string $op,array $body)use(&$calls,&$road):array{$calls[]=$op;return $op==='geocode'?['latitude'=>43.65,'longitude'=>-79.38]:array_fill(0,count($body['origins']),$road);};
$discovery=new LocationDiscoveryService($database,$config,$transport);$travel=new TravelEnquiryService($database,$discovery);
$count=0;$assert=function(bool $ok,string $label)use(&$count){if(!$ok)throw new RuntimeException($label);$count++;};
$deny=function(callable $run,string $code)use($assert){try{$run();}catch(ApiException $e){$assert($e->errorCode===$code,'Expected '.$code.', received '.$e->errorCode);return;}throw new RuntimeException('Expected '.$code);};
$point=['latitude'=>43.7,'longitude'=>-79.4];
$assert($discovery->settings()===['extra_km'=>25,'cap_km'=>100,'revision'=>1],'Default settings survive repeat migration');
foreach([[50000,50,true,'within_area'],[50001,50,true,'enquiry_only'],[75000,50,true,'enquiry_only'],[75001,50,true,null],[60000,50,false,null],[100000,150,true,'within_area'],[100001,150,true,null],[0,0,true,null]] as [$meters,$max,$extra,$expected])$assert(LocationDiscoveryService::status($meters,$max,$extra,$discovery->settings())===$expected,'Threshold boundary');
$assert(LocationDiscoveryService::straightDistance($point,$point)===0.0,'Coincident points');
foreach([null,[],['latitude'=>91,'longitude'=>0],['latitude'=>0,'longitude'=>INF],['latitude'=>'43','longitude'=>-79],['latitude'=>0,'longitude'=>0,'secret'=>1]] as $bad)$deny(fn()=>LocationDiscoveryService::point($bad),'validation_error');
$result=$discovery->search(1,['point'=>$point],'synthetic-ip');$assert(count($result['matches'])===1,'Extended match discovered');$match=$result['matches'][0];
$assert($match['status']==='enquiry_only'&&$match['starting_price_cents']===10000,'Enquiry status and eligible price');
$assert(!preg_match('/address_line|postal_code|distance_meters|origin|latitude/',json_encode($match)),'Public match reveals no origin or exact distance');
$assert($discovery->search(1,['point'=>$point,'only_within'=>true],'synthetic-ip')['matches']===[],'Normal coverage filter');
$before=count($calls);$discovery->search(1,['point'=>$point],'synthetic-ip');$assert(count($calls)===$before,'Private map cache avoids repeat provider calls');
$assert($discovery->search(2,['point'=>$point],'synthetic-ip')['matches']===[],'Clinic isolation');
$pdo->exec('UPDATE practitioner_locations SET active=0 WHERE practitioner_id=3');
$assert($discovery->search(1,['point'=>$point],'synthetic-ip')['matches']===[],'Inactive location assignment cannot be discovered');
$pdo->exec('UPDATE practitioner_locations SET active=1 WHERE practitioner_id=3');
$pdo->exec('UPDATE public_team_profiles SET published=0 WHERE user_id=2');
$assert($discovery->search(1,['point'=>$point],'synthetic-ip')['matches']===[],'Unpublished practitioner is hidden');
$pdo->exec('UPDATE public_team_profiles SET published=1 WHERE user_id=2');
$pdo->exec('UPDATE services SET published=0 WHERE id=4');
$assert($discovery->search(1,['point'=>$point],'synthetic-ip')['matches']===[],'Unpublished service is hidden');
$pdo->exec('UPDATE services SET published=1 WHERE id=4');
$practitioner=new AuthContext(2,1,'','','','staff',['practitioner']);$otherClient=new AuthContext(9,1,'','','','client',[]);$cross=new AuthContext(10,2,'','','','client',[]);
$assert($discovery->preferences($practitioner)['items'][0]['allow_extra']===true,'Default opt-in');
$discovery->preferences($practitioner,['service_id'=>4,'allow_extra'=>false],'test');
$assert($discovery->search(1,['point'=>$point],'synthetic-ip')['matches']===[],'Practitioner opt-out hides extra travel');
$deny(fn()=>$discovery->verify(1,$match['token']),'travel_enquiry_unavailable');
$discovery->preferences($practitioner,['service_id'=>4,'allow_extra'=>true],'test');
$deny(fn()=>$discovery->preferences($client),'forbidden');
$deny(fn()=>$discovery->preferences($practitioner,['service_id'=>999,'allow_extra'=>true],'test'),'assignment_not_found');
$deny(fn()=>$discovery->verify(2,$match['token']),'search_expired');$deny(fn()=>$discovery->verify(1,'tampered'),'search_expired');
$body=['reference'=>'11111111-1111-4111-8111-111111111111','token'=>$match['token'],'search_label'=>'Synthetic visit area','message'=>'Would you consider this extra journey?'];
$id=$travel->create($client,$body,'test')['id'];$assert($travel->create($client,$body,'test')['id']===$id,'Idempotent enquiry');
$deny(fn()=>$travel->create($client,array_replace($body,['message'=>'Changed']),'test'),'idempotency_conflict');
$assert($travel->list($practitioner)['unread_count']===1,'Practitioner unread notification');
$assert($travel->list($otherClient)['items']===[],'Other clients cannot list enquiries');
$deny(fn()=>$travel->detail($otherClient,$id),'enquiry_not_found');$deny(fn()=>$travel->detail($cross,$id),'enquiry_not_found');
$otherPractitioner=new AuthContext(1,1,'','','','staff',['practitioner']);$deny(fn()=>$travel->detail($otherPractitioner,$id),'enquiry_not_found');
$detail=$travel->detail($practitioner,$id);$assert(count($detail['messages'])===1,'Initial message stored');
$travel->act($practitioner,$id,'read',['message_id'=>(int)$detail['messages'][0]['id']],'test');$assert($travel->list($practitioner)['unread_count']===0,'Read acknowledgement');
$reply=['reference'=>'22222222-2222-4222-8222-222222222222','message'=>'Please contact clinic staff to arrange this.'];
$travel->act($practitioner,$id,'reply',$reply,'test');$travel->act($practitioner,$id,'reply',$reply,'test');
$assert(count($travel->detail($client,$id)['messages'])===2,'Reply retry is duplicate-safe');$assert($travel->list($client)['unread_count']===1,'Client unread notification');
$deny(fn()=>$travel->act($practitioner,$id,'reply',array_replace($reply,['message'=>'Changed']),'test'),'idempotency_conflict');
$deny(fn()=>$travel->act($client,$id,'close',[],'test'),'forbidden');
$travel->act($admin,$id,'close',[],'test');$assert($travel->detail($client,$id)['status']==='closed','Staff closes enquiry');
$travel->act($practitioner,$id,'reply',$reply,'test');
$deny(fn()=>$travel->act($client,$id,'reply',['reference'=>'33333333-3333-4333-8333-333333333333','message'=>'New'],'test'),'enquiry_closed');
$platform=new ApplicationAdminContext(1,new VerifiedIdentity('synthetic','https://synthetic.test','global','test'),'Admin','admin@example.test');
$assert($discovery->saveSettings($platform,['extra_km'=>10,'cap_km'=>55,'revision'=>1],'test')['revision']===2,'Global revisioned settings');
$deny(fn()=>$discovery->saveSettings($platform,['extra_km'=>25,'cap_km'=>100,'revision'=>1],'test'),'settings_changed');
$assert($discovery->search(1,['point'=>$point],'synthetic-ip')['matches']===[],'Global cap hides cached distance');
$discovery->saveSettings($platform,['extra_km'=>25,'cap_km'=>100,'revision'=>2],'test');
$pdo->exec('DELETE FROM discovery_distances');$road=100001;
$pdo->exec('UPDATE practitioner_services SET mobile_radius_km=150 WHERE practitioner_id=3 AND service_id=4');
$assert($discovery->search(1,['point'=>$point],'synthetic-ip')['matches']===[],'Driving distance beyond cap is hidden even inside normal maximum');
$pdo->exec('DELETE FROM discovery_distances');$road=null;
$assert($discovery->search(1,['point'=>$point],'synthetic-ip')['matches']===[],'No route is excluded rather than treated as zero');
$pdo->exec('DELETE FROM discovery_distances');$road=60000;
$failure=new LocationDiscoveryService($database,$config,fn()=>throw new ApiException(503,'synthetic_provider_down','Synthetic failure'));
$deny(fn()=>$failure->search(1,['point'=>$point],'synthetic-ip'),'synthetic_provider_down');
$pdo->exec('UPDATE practitioner_services SET mobile_radius_km=50 WHERE practitioner_id=3 AND service_id=4');
$assert((int)$pdo->query('SELECT mobile_radius_km FROM practitioner_services WHERE practitioner_id=3 AND service_id=4')->fetchColumn()===50,'Enquiries leave booking maximum unchanged');
$assert((int)$pdo->query("SELECT COUNT(*) FROM audit_logs WHERE metadata LIKE '%Synthetic visit area%' OR metadata LIKE '%extra journey%'")->fetchColumn()===0,'Audit excludes message and location text');
$discovery->limit('quota-test',1,'202610181200');$deny(fn()=>$discovery->limit('quota-test',1,'202610181200'),'rate_limited');
$assert(!$pdo->inTransaction(),'No transaction leaked');
foreach(['preflight','postflight'] as $phase){
    $sql=preg_replace('/^--.*$/m','',file_get_contents(dirname(__DIR__,2).'/database/maintenance/location-discovery-'.$phase.'.sql'));
    $sets=[];foreach(explode(';',$sql) as $statement){if(trim($statement)==='')continue;$q=$pdo->query($statement);$sets[]=$q->fetchAll();$q->closeCursor();}
    if($phase==='preflight'){$assert($sets[0][0]['selected_database']===$name,'Preflight uses selected schema');$assert(array_unique(array_column($sets[1],'prerequisite'))===['OK']&&array_unique(array_column($sets[2],'prerequisite'))===['OK'],'All deployment prerequisites verified');}
    else $assert(count($sets[0])===8&&$sets[1][0]['extra_km']==25&&$sets[1][0]['cap_km']==100,'Postflight verifies eight tables and configured settings');
}
echo "Location discovery and travel enquiries SQL: $count checks passed.\n";
